// client/src/features/dashboard/attendee/AttendeeDashboard.jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  const [events, setEvents]     = useState([]);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState(null);
  const [pendingPay, setPendingPay]       = useState(null);   // eventId awaiting payment
  const [registeredIds, setRegisteredIds] = useState([]);

  // fetch all events
  const fetchEvents = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res   = await axios.get(
        'http://localhost:5000/api/attendee/events',
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setEvents(res.data.events);
      setError(null);
    } catch {
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchEvents(); }, []);

  // Step 1: User clicks “Register”
  const handleRegisterClick = (eventId) => {
    setPendingPay(eventId);
  };

  // Step 2: User clicks “Pay Now”
  const handlePayNow = async () => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        'http://localhost:5000/api/attendee/register',
        { eventId: pendingPay },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setRegisteredIds(ids => [...ids, pendingPay]);
      setPendingPay(null);
    } catch {
      alert('Registration/payment failed');
    }
  };

  // split out
  const upcoming   = events.filter(e => !registeredIds.includes(e._id));
  const registered = events.filter(e => registeredIds.includes(e._id));

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>

        {/* Upcoming Events */}
        <section>
          <h3>Upcoming Events</h3>
          {loading
            ? <p>Loading…</p>
            : error
              ? <p style={{ color: 'red' }}>{error}</p>
              : upcoming.length === 0
                ? <p>No upcoming events.</p>
                : <ul>
                    {upcoming.map(evt => (
                      <li key={evt._id} style={{ marginBottom: '0.75rem' }}>
                        <strong>{evt.title}</strong> | {new Date(evt.date).toLocaleString()}<br/>

                        {pendingPay === evt._id
                          ? <button className="btn" onClick={handlePayNow}>
                              Pay Now
                            </button>
                          : <button
                              className="btn"
                              onClick={() => handleRegisterClick(evt._id)}
                            >
                              Register
                            </button>
                        }
                      </li>
                    ))}
                  </ul>
          }
        </section>

        {/* Registered Events */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Registered Events</h3>
          {registered.length === 0
            ? <p>You haven’t registered (and paid) for any events yet.</p>
            : <ul>
                {registered.map(evt => (
                  <li key={evt._id} style={{ marginBottom: '0.75rem' }}>
                    <strong>{evt.title}</strong> | {new Date(evt.date).toLocaleString()}<br/>
                    {/* Later: Show “Join Session” link here */}
                    <em>Registration confirmed</em>
                  </li>
                ))}
              </ul>
          }
        </section>
      </div>
    </div>
  );
};

export default AttendeeDashboard;
